<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{teacherAPI}from'../../api/teacher';import type{MentorCandidate,Organization}from'../../api/types';import{APIError}from'../../api/client';import StatusBadge from'../../components/StatusBadge.vue';import AppDialog from'../../components/AppDialog.vue';import LoadingRegion from'../../components/LoadingRegion.vue';import{useLoadState}from'../../composables/useLoadState';import{useToast}from'../../composables/useToast';const rows=ref<Organization[]>([]),drawer=ref(false),editing=ref<Organization|null>(null),assignOrg=ref<Organization|null>(null),candidates=ref<MentorCandidate[]>([]),query=ref(''),cursor=ref<string|null>(null),inviteOpen=ref(false),inviteEmail=ref(''),error=ref(''),toast=useToast(),loadState=useLoadState(),candidateLoadState=useLoadState(),form=reactive({name:'',description:'',status:'active' as'active'|'inactive'});async function load(){await loadState.run(async()=>{try{rows.value=await teacherAPI.organizations()}catch(e){error.value=msg(e)}})}function open(row?:Organization){editing.value=row??null;Object.assign(form,{name:row?.name??'',description:row?.description??'',status:row?.status??'active'});drawer.value=true}async function save(){try{if(editing.value)await teacherAPI.updateOrganization(editing.value.id,form);else await teacherAPI.createOrganization(form);toast.success(editing.value?'组织已更新':'组织已创建');await load();if(!editing.value)drawer.value=false}catch(e){error.value=msg(e)}}async function toggle(row:Organization){if(row.status==='active'&&!confirm('停用组织将阻止新的学生申请，是否继续？'))return;try{await teacherAPI.updateOrganization(row.id,{status:row.status==='active'?'inactive':'active'});await load()}catch(e){error.value=msg(e)}}async function search(reset=true){const organization=assignOrg.value;if(!organization)return;await candidateLoadState.run(async()=>{try{const page=await teacherAPI.mentorCandidates(organization.id,query.value,reset?'':cursor.value??'',20);candidates.value=reset?page.data:[...candidates.value,...page.data];cursor.value=page.meta.next_cursor??null}catch(e){error.value=msg(e)}})}async function assign(candidate:MentorCandidate){if(!assignOrg.value||candidate.is_member||!confirm(`确认将 ${candidate.name} 分配到 ${assignOrg.value.name}？`))return;try{await teacherAPI.assignMentor(assignOrg.value.id,candidate.id);toast.success('导师已加入组织');await search()}catch(e){error.value=msg(e)}}async function invite(){try{await teacherAPI.invite(inviteEmail.value);toast.success('老师邀请已发送');inviteOpen.value=false;inviteEmail.value=''}catch(e){error.value=msg(e)}}function msg(e:unknown){return e instanceof APIError?e.message:'请求失败'};onMounted(load);</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">TEACHER</p><h1>组织管理</h1><p class="muted">维护组织、分配导师并邀请老师。</p></div><div class="actions"><button class="button secondary" @click="inviteOpen=true">邀请老师</button><button class="button primary" @click="open()">添加组织</button></div></div><p v-if="error" class="error banner">{{error}}</p><LoadingRegion :initial-loading="loadState.initialLoading.value" :refreshing="loadState.refreshing.value" variant="list" label="正在加载组织"><section class="panel"><div class="table"><article v-for="row in rows" :key="row.id" class="list-row"><div><strong>{{row.name}}</strong><p class="muted">{{row.description||'暂无说明'}}</p></div><div class="actions"><StatusBadge :status="row.status"/><button class="button ghost" @click="open(row)">编辑</button><button class="button ghost" @click="assignOrg=row;query='';search()">分配导师</button><button class="button" :class="row.status==='active'?'danger':'secondary'" @click="toggle(row)">{{row.status==='active'?'停用':'启用'}}</button></div></article></div></section></LoadingRegion><AppDialog :open="drawer" :title="editing?'编辑组织':'创建组织'" @update:open="drawer=$event"><form @submit.prevent="save"><label>名称<input v-model="form.name" maxlength="128" required/></label><label>说明<textarea v-model="form.description" rows="4"/></label><label>状态<select v-model="form.status"><option value="active">启用</option><option value="inactive">停用</option></select></label><div class="actions"><button class="button primary">保存</button></div></form></AppDialog><AppDialog :open="Boolean(assignOrg)" :title="`分配导师 · ${assignOrg?.name||''}`" @update:open="assignOrg=$event?assignOrg:null"><LoadingRegion :initial-loading="candidateLoadState.initialLoading.value" :refreshing="candidateLoadState.refreshing.value" variant="list" label="正在加载导师候选"><div class="row"><input v-model="query" placeholder="搜索姓名或邮箱" @keyup.enter="search()"/><button class="button secondary" @click="search()">搜索</button></div><article v-for="candidate in candidates" :key="candidate.id" class="list-row"><div><strong>{{candidate.name}}</strong><p class="muted">{{candidate.email}}</p></div><button class="button primary" :disabled="candidate.is_member" @click="assign(candidate)">{{candidate.is_member?'已加入':'分配'}}</button></article><button v-if="cursor" class="button ghost wide" @click="search(false)">加载更多</button></LoadingRegion></AppDialog><AppDialog :open="inviteOpen" title="邀请老师" @update:open="inviteOpen=$event"><label>老师邮箱<input v-model="inviteEmail" type="email" required/></label><div class="actions"><button class="button primary" @click="invite">发送邀请</button></div></AppDialog></section></template>
